
<main class="background">
    <div class="stars"></div>
    <div class="stars-revert"></div>
    <slot/>
</main>

<style>

    @keyframes orb{
        from {
            transform: rotate(0deg);
        }
        to{
            transform: rotate(360deg);
        }
    }

    .background {
        margin: 0 auto;
        width: 100%;
        height: 100%;
        display: flex;
        flex-grow: 1;
        position: relative;
        background: radial-gradient(ellipse at bottom, #1C2837 0%, #050608 100%);
        background-attachment: fixed;
        overflow: hidden;
    }

    .stars {
        position: absolute;
        width: 100%;
        height: 100%;
        animation: orb 800s linear infinite;
    }

    .stars-revert {
        opacity: 0.5;
        position: absolute;
        width: 100%;
        height: 100%;
        left: 50%;
        /* animation: orb 180s linear infinite; */
    }

